html:
{%- set company = frappe.get_doc('Company', doc.company) -%}
{%- set currency = doc.currency or company.default_currency or '' -%}
{%- set has_pms = doc.dw_has_pms_items -%}
<style>
  .dw-pos-receipt { font-family: Arial, Helvetica, sans-serif; font-size: 10px; color: #111; width: 74mm; }
  .dw-pos-receipt .center { text-align: center; }
  .dw-pos-receipt .strong { font-weight: 700; }
  .dw-pos-receipt .muted { color: #666; }
  .dw-pos-receipt .row { display: flex; justify-content: space-between; gap: 8px; margin: 2px 0; }
  .dw-pos-receipt .rule { border-top: 1px dashed #555; margin: 6px 0; }
  .dw-pos-receipt table { width: 100%; border-collapse: collapse; }
  .dw-pos-receipt td { padding: 2px 0; vertical-align: top; }
  .dw-pos-receipt .qty { width: 12%; }
  .dw-pos-receipt .desc { width: 56%; }
  .dw-pos-receipt .amt { width: 32%; text-align: right; }
</style>
<div class="dw-pos-receipt">
  <div class="center strong">{{ company.company_name }}</div>
  {%- if company.company_address %}<div class="center muted">{{ company.company_address }}</div>{%- endif %}
  {%- if company.phone_no %}<div class="center muted">{{ company.phone_no }}</div>{%- endif %}
  <div class="rule"></div>
  <div class="row"><span>Invoice</span><span>{{ doc.name }}</span></div>
  <div class="row"><span>Date</span><span>{{ frappe.format_date(doc.posting_date) }}</span></div>
  <div class="row"><span>Customer</span><span>{{ doc.customer_name or doc.customer }}</span></div>
  {%- if doc.dw_pos_sales_person %}<div class="row"><span>Sales</span><span>{{ doc.dw_pos_sales_person }}</span></div>{%- endif %}
  <div class="rule"></div>
  <table>
    {%- for item in doc.items %}
    <tr>
      <td class="qty">{{ item.qty }}</td>
      <td class="desc">{{ item.item_name or item.item_code }}</td>
      <td class="amt">{{ frappe.utils.fmt_money(item.amount, currency=currency or None) }}</td>
    </tr>
    {%- endfor %}
  </table>
  <div class="rule"></div>
  <div class="row"><span>Subtotal</span><span>{{ frappe.utils.fmt_money(doc.net_total or doc.total, currency=currency or None) }}</span></div>
  {%- if doc.discount_amount %}<div class="row"><span>Discount</span><span>-{{ frappe.utils.fmt_money(doc.discount_amount, currency=currency or None) }}</span></div>{%- endif %}
  {%- if not has_pms and doc.total_taxes_and_charges %}<div class="row"><span>Tax</span><span>{{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=currency or None) }}</span></div>{%- endif %}
  <div class="row strong"><span>Total</span><span>{{ frappe.utils.fmt_money(doc.grand_total, currency=currency or None) }}</span></div>
  {%- if doc.payments and doc.payments | length > 0 %}<div class="rule"></div>{%- for payment in doc.payments %}<div class="row"><span>{{ payment.mode_of_payment }}</span><span>{{ frappe.utils.fmt_money(payment.amount, currency=currency or None) }}</span></div>{%- endfor %}{%- endif %}
  {%- if has_pms and doc.dw_pms_disclaimer %}<div class="rule"></div><div class="center muted">{{ doc.dw_pms_disclaimer }}</div>{%- endif %}
  <div class="rule"></div>
  <div class="center muted">Thank you for your business.</div>
</div>
